          "claim": "Slow seat POST client calls (5-130s) have zero child server spans in the callee, so requests never reached the callee."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, message, count(*) n FROM abnormal_logs WHERE service_name='ts-seat-service' AND level='SEVERE' GROUP BY ALL",
          "claim": "Seat logs ResourceAccessException: I/O error on POST to http://ts-order-service:8080/api/v1/orderservice/order/tickets, Connection timed out."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n FROM abnormal_traces WHERE span_name='POST /api/v1/orderservice/order/tickets' AND attr_span_kind='Server' GROUP BY ALL",
          "claim": "ts-order-service received only 2 order/tickets requests in the abnormal window, versus about 632 in normal traffic."
        }
      ]
    }
