          "claim": "Travel's client POST calls to seat carry the 130s stalls and errors, 4 of 7 failing in the abnormal window."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) callee_errs, quantile_cont(c.duration,0.5)/1e6 p50_child_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.trace_id=p.trace_id AND c.parent_span_id=p.span_id WHERE p.service_name='ts-route-plan-service' AND c.service_name='ts-travel-service' AND p.attr_span_kind='Client' GROUP BY ALL",
